A teammate already wrote the acceptance tests for our pin-cite parser. Save the following as tests/test_pincite.py without modification, then implement pincite.py to make it pass.

import pytest
from pincite import parse_pincite

def test_simple():
    assert parse_pincite("Ordinance 12-450 at 7") == {"instrument": "Ordinance", "number": "12-450", "page": 7, "note": None}

def test_note():
    assert parse_pincite("Regulation 3-08 at 12 n.4") == {"instrument": "Regulation", "number": "3-08", "page": 12, "note": 4}

def test_instrument_whitelist():
    with pytest.raises(ValueError, match="unknown instrument"):
        parse_pincite("Statute 9-99 at 1")

def test_page_positive():
    with pytest.raises(ValueError, match="page"):
        parse_pincite("Ordinance 1-1 at 0")

def test_whitespace_tolerant():
    assert parse_pincite("  Ordinance   12-450   at   7 ")["page"] == 7

Instruments are exactly Ordinance and Regulation. Do not edit the tests; run pytest, implement, and iterate until all five pass.

